    def get_indices(self, start, end, depth=0):
        indices = []
        if start > end or not self.adj_list[start]:
            return indices
        if self.is_leaf_node(start):
            for node in self.adj_list[start]:
                indices.append((start - 1) * (depth + 1) + node)
        else:
            for node in self.adj_list[start]:
                indices.extend(self.get_indices(node, end, depth + 1))
        return indices

    def get_sequence(self):
