from collections import defaultdict

def find_array(m, copies):
    # Convert array values to tuples for easier comparison
    indexed_copies = [(i, tuple(copies[i])) for i in range(m)]

    # Initial check if the array matches
    best_match = monarchy_match = min_copies = 0
    for i, copy in sorted(indexed_copies):
        if monarchy_match < min_copies:
            monarchy_match = min_copies = i
            best_match = monarchy_match

    if min_copies == 0:
        return "No"

    best_match_copy = monarchy_match
    # Iterate through the copies again to find the original array maximizing match counts
    for i, copy in indexed_copies:
        if best_match // i == i != best_match_copy // i:
            best_match = copy
            break

    return "Yes\n" + " ".join(str(best_match[j] % i) for j in range(m))

def monarchy_match(i, copy):
    if i == 1:
        return all(x / i == y for x, y in copy)
    else:
        counts = defaultdict(int)
        for num in copy:
            counts[num % (i * j)] += 1
        for num in range(1, (i-1) // 2 + 1):
            counts[num * i] += counts[num]
            if counts[num * i] == i:
                return True
        for num in range(1, i // 2 + 1):
            if counts[num * i] == i - 1 and counts[num * i] != i // 2:
                return True
        return False

