import math

def fold_area(polygon, fold):
    p = []
    for h in polygon:
        if h[1] > fold:
            p.append((h[1], h[0]))

    res = 0
    i = 0
    while True:
        h1, v1 = p[i][0] - fold, p[i][1]
        i = i + 1
        h2, v2 = h1, v1
        while True:
            dep_h, dep_v = p[i][0] - fold, p[i][1]
            res += v1 * dep_v - v2 * dep_h
            if h2 >= dep_h:
                i += 1
                h1, v1 = h2, v2
                h2, v2 = dep_h, dep_v
            elif h2 > 0 < h1:
                break
            elif v2 < 0:
                break

    return res

