from collections import defaultdict

def min_s(sequence):
    length = len(sequence)
    dp = [0] * (length + 1)
    dp[1] = len(sequence[0])
    min_dp = float('inf')

    prefix_len = {0}
    queue = [(0, 0)]
    visited = set([0, 1])

    while queue:
        cur_len, prefix = queue.pop()
        if prefix >= dp[cur_len - 1]:
            for suffix in visited:
                if suffix > (prefix - cur_len + 1) // 2 * 2:
                    if len(dp) - cur_len > suffix - len(sequence[-cur_len]) * 2:
                        dp[cur_len] = len(sequence[-cur_len]) + dp[-cur_len - 2]
                    else:
                        dp[cur_len] = len(sequence[-cur_len - suffix + 1]) + prefix_len[prefix - suffix]
                new_prefix = suffix
                while new_prefix - cur_len + 1 - len(sequence[-cur_len]) * 2 > 0:
                    new_prefix -= len(sequence[-cur_len]) * 2
                    if new_prefix not in visited:
                        visited.add(new_prefix)
                        dp[new_prefix] = len(sequence)
                        queue.append((new_prefix, new_prefix))

    return None if dp[-1] > length else dp[-1]

