import sys

def find_rook_path(M, marked_squares):
    used_rows = set()
    used_cols = set()
    path = []
    for squares in marked_squares:
        r, c = squares
        if r in used_rows or c in used_cols:
            continue
        if r == 0:
            path.append(squares)
            used_cols.add(c)
        elif c == 0:
            path.append(squares)
            used_rows.add(r)
        else:
            path.append(squares)
            used_rows.add(r)
            used_cols.add(c)
    if len(path) != 2 * M:
        raise ValueError("The path does not visit each marked square exactly once")
    return path

def solve(N, M, marked_squares):
    rook_path = find_rook_path(M, marked_squares)
    return " ".join(map(str, rook_path))

