from typing import List

def process_query_type_one(a: List[int], l: int, r: int) -> None:
    n = len(a)
    a = list(map(lambda x: x % n, a))
    if l < r:
        a[l], a[r] = a[r], a[l]
        for i in range(1, r - l):
            if a[(l + i) % n] < a[(l + i + 1) % n]:
                a[(l + i) % n], a[(l + i + 1) % n] = a[(l + i + 1) % n], a[(l + i) % n]
    else:
        shift = (n + 1) % n - 1
        for i in range(1, n - l):
            a[(n - l) + i] = a[(n - l) + i + 1]
        swap_l = l - shift
        swap_r = n - l
        for i in range(max(swap_l, swap_r - 1)):
            if a[i] < a[i + 1]:
                a[i], a[i + 1] = a[i + 1], a[i]
        swap_r += shift
        if l - swap_l <= swap_r:
            ri, l = swap_l, swap_r
        elif swap_l + n - l <= swap_r:
            ri, l = swap_r, swap_l
        else:
            r = n + 1
        for i in range(r):
            if i > ri:
                i = n - i
                a[i] = (a[i] - 1) % n + 1
                if l <= i < n:
                    a[(n - 1) + i] = (a[n - 1 + i] - 1) % n + 1
                if l <= i < n and a[i] == a[i + 1]:
                    a[i + 1] -= 1
                continue
            if a[i] < a[i + 1]:
                r += 1
                swap_r += 1
            for j in range(i + 1, r):
                if a[j] >= a[swap_r]:
                    if a[i] > a[j]:
                        r += 1
                        swap_r += 1
                    ri = max(r, i + 1)
                    break
            if r == ri + 1:
                temp = a[i]
                a[i] = a[r - 1]
                a[r - 1] = temp
                r -= 2
    return a

