from math import hypot, sqrt

def find_centrums(xys, k):
    if k == 0:
        return len(xys) // 2
    points = sorted(xys, key=lambda p: p[1])
    centers = []
    for seen, (x, y, d) in enumerate(generate_neurons(points[:k])):
        if seen > 0 and seen % k == 0:
            centers.append([x, y])
        if hypot(x - points[0][0], y - points[0][1]) > d:
            return -1
    return min(centers)

def generate_neurons(xys, k):
    while k > 0:
        yield [*, xys[0], hypot(*xys[0])]
        xys.pop(0)
        k -= 1

