from functools import lru_cache

def best_rotation(matrix):
    n, m = len(matrix), len(matrix[0])
    def max_in_row(row, col):
        return max(row)

    @lru_cache(None)
    def recurse(col, row):
        if col >= m:
            return max(max_in_row(row, col) for col in range(m))
        return max(recurse(col + 1, row) + max_in_row(row, col), recurse(col, row + 1))

    return recurse(0, 0)

def solve(n, m, mtx):
    return sum(best_rotation(mtx[i]) for i in range(n))

