from collections import defaultdict

def balance_scales(n, initial_weights, scale_info):
    # Create a graph where each node represents a scale
    edges = defaultdict(list)
    for i in range(n):
        row_weights = scale_info[i]
        edges[i].extend(row_weights)

    bfs_results = {}
    for node in range(n * (n + 1) // 2):
        if node in bfs_results:
            continue
        queue = [node]
        visited = {node}
        while queue:
            current_node = queue.pop(0)
            for neighbor in edges[current_node]:
                if neighbor in visited:
                    continue
                visited.add(neighbor)
                queue.append(neighbor)

        weight_sum = sum(initial_weights[node] for node in bfs_results.keys() if node in bfs_results)
        for weight in bfs_results.values():
            if weight_sum - weight >= weight_sum:
                return "Cerealguy"
    return "Fat Rat"

