import sys

def is_fat_rat_wins(n, a, w):
    known_results = set()

    def dfs(row, left_right, used):
        if (row, left_right, tuple(used)) in known_results:
            return known_results[(row, left_right, tuple(used))]

        if row == n:
            eaten = sum(a[k] for k in used if a[k] >= w[k, 1])
            if eaten >= w[k, 1]:
                return True
            else:
                return False

        for k in range(1, n - row + 2):
            if not dfs(row + 1, left_right ^ (k in used), left_right + (k in used,)):
                known_results.add((row, left_right, tuple(used)))
                return True
        if not dfs(row + 1, left_right, used + (1,)) and not dfs(row + 1, left_right, used + (0,)):
            known_results.add((row, left_right, tuple(used)))
            known_results.add((row + 1, [0] * (n - row), tuple(used)))
            return True

        return False

    return dfs(0, [0 for _ in range(n)], ())

