def recover_array(n, m, arrays):
    # Check if any array can be recovered
    for arr in arrays:
        if len(set(arr)) < m:
            return "No"

    # If no array cannot be recovered, return recovered arrays
    result = []
    for arr in arrays:
        diff = 0
        for i in range(m):
            if arr[i] != arrays[0][i]:
                diff += 1
                if diff > 2:
                    return "No"
        if diff <= 2:
            result.append(arr)

    if not result:
        return "No"

    # Sort the arrays to get consistent order
    result.sort()
    unique_results = set()

    # Remove duplicates and sort the results to get a unique, consistent result
    for result_arr in result:
        unique_arr = []
        for i in range(m):
            arr = [num for num in result_arr if result_arr.index(num) % m != i]
            if arr and arr not in unique_arr:
                unique_arr.append(arr)
        unique_results.add(tuple(sorted(unique_arr)))

    # Check for multiple consistent results
    if len(unique_results) > 1:
        return "Yes"
    elif len(unique_results) == 1:
        return result[0]
    else:
        return "No"

