from collections import deque

def compress_sequence(sequence):
    stack = deque([])
    stack.append([sequence[0]])
    for i in range(1, len(sequence)):
        if stack and stack[-1][-1] == sequence[i]:
            stack[-1].append(sequence[i])
        else:
            stack.append([sequence[i]])
    return "".join([seq[0] for seq in stack])

def minimum_S(length_of_sequence, sequences):
    if not sequences:
        return 0
    compressed_sequence = compress_sequence(sequences)
    for i in range(1, len(sequences)):
        compressed_sequence = compressed_sequence.replace(sequences[i-1], compressed_sequence[compressed_sequence.find(sequences[i-1]):compressed_sequence.find(sequences[i-1])+len(sequences[i-1])].replace(sequences[i-1], sequences[i-1]+sequences[i]).replace(sequences[i-1], sequences[i-1], 1))
