from collections import defaultdict
from math import sqrt

def compute_centers(surviving_points, k):
    centers = {}
    layers = defaultdict(list)

    # Counting points up to k layers
    for point in surviving_points:
        x, y = point
        for _ in range(k + 1):
            root = (x, y)
            if root not in layers:
                layers[root].append(point)
            elif len(layers[root]) > 1:
                return -1  # More than k points would coincide due to symmetry
            if point not in layers[root]:
                layers[root].append(point)
            x, y = (-y, x)

    for root, points in layers.items():
        intersection = set(a - b for a, b in zip(root, points[0]))
        if len(intersection) == 1:
            point = next(iter(intersection))
            center = (point[0] + points[1][0] - root[0]) / 2, (point[1] + points[1][1] - root[1]) / 2
            centers[root] = center

    return len(centers)

